"""Genera schede originali, tracce e quiz numerici da problemi con dati SI.
Le espressioni sono valutate con SymPy; i dati e i risultati restano nel rapporto JSON.
"""
from pathlib import Path
import json, math, re
import sympy as sp
from extra_problemi import EXTRA

ROOT=Path(__file__).resolve().parents[2]
M='fisica-superiori-4'
OUT=ROOT/'src/content'
CH=json.loads((Path(__file__).parent/'capitoli.json').read_text())
BANK={x[0]:[] for x in CH}
AUDIT=[]

def num(v):
    v=float(v)
    if v==0: return '0'
    s=f'{v:.3g}'
    if 'e' in s:
        mantissa,exponent=s.split('e')
        return mantissa.replace('.','{,}')+r'\cdot10^{'+str(int(exponent))+'}'
    return s.replace('.','{,}')

def add(ch,anchor,title,prompt,target,formula,expr,unit,values,why,scale=None):
    # Ogni serie cambia un dato reale mantenendo gli altri e le ipotesi del problema.
    # Le serie 1-2 alimentano gli svolti, 3-4 le tracce, 5-8 i quiz.
    BANK[ch].append(dict(anchor=anchor,title=title,prompt=prompt,target=target,formula=formula,expr=expr,unit=unit,values=values,why=why,scale=scale))

# Temperatura, calore e gas
c=CH[0][0]
add(c,'calorimetria','Riscaldamenti senza cambiamenti di stato',r'Una massa di acqua $m=@m@\,\mathrm{kg}$ viene riscaldata di $\Delta T=@dt@\,\mathrm K$. Assumi $c=4180\,\mathrm{J/(kg\,K)}$ costante e assenza di passaggi di stato. Calcola il calore assorbito.', 'Q',r'Q=mc\Delta T','m*4180*dt','J',{'m':.35,'dt':24},'Non avvengono passaggi di stato, quindi il calore aumenta la temperatura secondo la legge calorimetrica. La massa è in chilogrammi e la variazione termica in kelvin. Il risultato è positivo perché il corpo si riscalda.', 'Se la massa raddoppia con lo stesso aumento di temperatura, anche il calore richiesto raddoppia.')
add(c,'dilatazione','Dilatazioni di sbarre',r'Una sbarra libera di dilatarsi ha lunghezza $L_0=@L@\,\mathrm m$ e coefficiente $\alpha=1{,}2\cdot10^{-5}\,\mathrm{K^{-1}}$. La temperatura aumenta di $\Delta T=@dt@\,\mathrm K$. Calcola l’allungamento nel modello lineare.',r'\Delta L',r'\Delta L=\alpha L_0\Delta T','1.2e-5*L*dt','m',{'L':2.5,'dt':40},'Il coefficiente si riferisce alla dilatazione lineare. La variazione cercata è la differenza tra lunghezza finale e iniziale, quindi si usa la lunghezza iniziale nel prodotto. Il valore ottenuto è molto minore di quella lunghezza, coerentemente con il modello.','Raddoppiare la lunghezza iniziale raddoppia l’allungamento alle stesse condizioni termiche.')
add(c,'equilibrio-calorimetrico','Mescolamenti di acqua',r'In un recipiente isolato con capacità termica trascurabile si mescolano $m_h=@mh@\,\mathrm{kg}$ di acqua a $t_h=70\,{}^\circ\mathrm C$ e $m_c=@mc@\,\mathrm{kg}$ a $t_c=20\,{}^\circ\mathrm C$. Calcola la temperatura finale, assumendo lo stesso calore specifico costante.',r't_f',r'm_hc(t_f-t_h)+m_cc(t_f-t_c)=0','(mh*70+mc*20)/(mh+mc)',r'{}^\circ C',{'mh':.25,'mc':.40},'Il recipiente non scambia energia con l’esterno e non assorbe una quantità apprezzabile di calore. Il calore ceduto dall’acqua calda è uguale a quello assorbito dalla fredda. Il calore specifico comune si semplifica e la temperatura finale è una media pesata dalle masse.','La temperatura deve essere compresa fra 20 e 70 gradi Celsius; una temperatura esterna a questo intervallo sarebbe incompatibile con i dati.')
add(c,'calore-latente','Fusioni complete del ghiaccio',r'Una massa di ghiaccio $m=@m@\,\mathrm{kg}$ è già a $0\,{}^\circ\mathrm C$. Calcola l’energia per fonderla completamente alla pressione atmosferica, usando $\ell_f=3{,}34\cdot10^5\,\mathrm{J/kg}$.','Q',r'Q=m\ell_f','m*3.34e5','J',{'m':.12},'Durante la fusione la temperatura rimane quella di equilibrio. L’energia modifica la fase della materia, quindi si usa il calore latente e non il prodotto del calore specifico per una variazione di temperatura.','Una massa doppia richiede energia doppia per la fusione completa.')
add(c,'calore-latente','Fusioni seguite dal riscaldamento',r'Una massa $m=@m@\,\mathrm{kg}$ di ghiaccio a $0\,{}^\circ\mathrm C$ deve diventare acqua a $t_f=@tf@\,{}^\circ\mathrm C$. Assumi $\ell_f=3{,}34\cdot10^5\,\mathrm{J/kg}$ e $c=4180\,\mathrm{J/(kg\,K)}$, senza dispersioni. Calcola l’energia totale.','Q',r'Q=m\ell_f+mc(t_f-0)','m*(3.34e5+4180*tf)','J',{'m':.18,'tf':30},'La trasformazione comprende due stadi. Prima si fonde tutta la massa a temperatura costante; poi si riscalda l’acqua prodotta. I contributi energetici sono entrambi positivi e si sommano.','Il riscaldamento dell’acqua richiede energia aggiuntiva rispetto alla sola fusione.')
add(c,'gas-ideale','Pressioni di gas ideali',r'Un gas ideale in equilibrio contiene $n=@n@\,\mathrm{mol}$ in un volume $V=@V@\,\mathrm{m^3}$ a $T=@T@\,\mathrm K$. Usa $R=8{,}314\,\mathrm{J/(mol\,K)}$ e calcola la pressione assoluta.','p',r'pV=nRT','n*8.314*T/V','Pa',{'n':.60,'V':.018,'T':310},'Il gas è trattato come ideale e tutte le grandezze sono in unità SI. Dall’equazione di stato si isola la pressione dividendo per il volume. La temperatura è già assoluta, quindi non si aggiunge alcuna costante.','A quantità di gas e temperatura fissate, un volume doppio darebbe pressione dimezzata.')
add(c,'gas-ideale','Confronti tra stati di un gas',r'Una quantità fissa di gas ideale passa da $p_1=@p1@\,\mathrm{Pa}$, $V_1=0{,}012\,\mathrm{m^3}$ e $T_1=300\,\mathrm K$ a $V_2=0{,}018\,\mathrm{m^3}$ e $T_2=@T2@\,\mathrm K$. Calcola $p_2$.','p_2',r'\frac{p_1V_1}{T_1}=\frac{p_2V_2}{T_2}','p1*.012*T2/(300*.018)','Pa',{'p1':1.4e5,'T2':360},'Il numero di moli è invariato, quindi il rapporto fra pressione per volume e temperatura assoluta è lo stesso nei due stati. Per ricavare la pressione finale si moltiplica per la temperatura finale e si divide per il volume finale.','Il rapporto delle temperature va costruito in kelvin.')
add(c,'trasmissione','Conduzioni attraverso pareti',r'Una parete piana omogenea di area $A=@A@\,\mathrm{m^2}$ e spessore $d=0{,}12\,\mathrm m$ separa due ambienti con differenza di temperatura $\Delta T=@dt@\,\mathrm K$. La conducibilità è $\kappa=0{,}050\,\mathrm{W/(m\,K)}$. Calcola la potenza termica trasferita in regime stazionario.','P',r'P=\kappa A\frac{\Delta T}{d}','.05*A*dt/.12','W',{'A':8,'dt':24},'La temperatura della parete ha raggiunto un profilo stazionario e la conducibilità è costante. La legge della conduzione fornisce direttamente l’energia trasferita per secondo. Il risultato è il modulo della potenza dal lato caldo a quello freddo.','Con le stesse condizioni, raddoppiare lo spessore dimezzerebbe la potenza trasferita.')

# Primo principio
c=CH[1][0]
add(c,'primo-principio','Bilanci con calore assorbito e lavoro compiuto',r'Un gas in un sistema chiuso assorbe $Q=@Q@\,\mathrm J$ e compie sull’ambiente un lavoro $W=@W@\,\mathrm J$. Trascurando variazioni macroscopiche di energia cinetica e potenziale, calcola la variazione di energia interna.',r'\Delta U',r'\Delta U=Q-W','Q-W','J',{'Q':900,'W':250},'Il calore entrante è positivo e il lavoro compiuto dal gas è positivo. Dal calore ricevuto si sottrae quindi l’energia trasferita all’ambiente attraverso il lavoro. La differenza resta come aumento di energia interna.')
add(c,'primo-principio','Calori ricavati dal bilancio energetico',r'Un gas aumenta la propria energia interna di $\Delta U=@du@\,\mathrm J$ e compie un lavoro $W=@W@\,\mathrm J$. Calcola il calore assorbito con la convenzione $\Delta U=Q-W$.','Q',r'Q=\Delta U+W','du+W','J',{'du':420,'W':180},'Si isola il calore nel primo principio. L’energia che entra deve coprire sia l’aumento di energia interna sia il lavoro compiuto all’esterno; i due contributi si sommano.')
add(c,'lavoro-volume','Lavori in trasformazioni isobare',r'Un gas si espande quasi staticamente a pressione costante $p=@p@\,\mathrm{Pa}$ da $V_i=0{,}002\,\mathrm{m^3}$ a $V_f=@Vf@\,\mathrm{m^3}$. Calcola il lavoro compiuto dal gas.','W',r'W=p(V_f-V_i)','p*(Vf-.002)','J',{'p':1.3e5,'Vf':.005},'La pressione resta costante, quindi il lavoro è l’area di un rettangolo nel diagramma pressione-volume. L’aumento di volume è positivo e il lavoro ha segno positivo nella convenzione adottata.')
add(c,'calori-molari','Variazioni di energia dei gas monoatomici',r'Un gas ideale monoatomico di $n=@n@\,\mathrm{mol}$ aumenta la temperatura di $\Delta T=@dt@\,\mathrm K$. Usa $R=8{,}314\,\mathrm{J/(mol\,K)}$ e calcola $\Delta U$.',r'\Delta U',r'\Delta U=\frac32nR\Delta T','1.5*n*8.314*dt','J',{'n':.8,'dt':45},'L’energia interna del gas ideale monoatomico classico dipende soltanto dalla temperatura. La formula della variazione vale indipendentemente dal cammino; non equivale automaticamente al calore scambiato.')
add(c,'isocora-isobara','Riscaldamenti isocori',r'Un recipiente rigido contiene $n=@n@\,\mathrm{mol}$ di gas ideale monoatomico. La temperatura aumenta di $\Delta T=@dt@\,\mathrm K$. L’unico lavoro possibile è quello di volume. Calcola il calore assorbito con $R=8{,}314\,\mathrm{J/(mol\,K)}$.','Q',r'W=0,\qquad Q=\Delta U=\frac32nR\Delta T','1.5*n*8.314*dt','J',{'n':1.2,'dt':35},'Il volume è costante, quindi il gas non compie lavoro di volume. Per il primo principio il calore coincide con la variazione di energia interna. Il calore molare del gas monoatomico a volume costante è tre mezzi della costante dei gas.')
add(c,'isocora-isobara','Riscaldamenti isobari',r'Un gas ideale monoatomico di $n=@n@\,\mathrm{mol}$ si riscalda quasi staticamente a pressione costante di $\Delta T=@dt@\,\mathrm K$. Calcola il calore assorbito usando $R=8{,}314\,\mathrm{J/(mol\,K)}$.','Q',r'Q=nC_p\Delta T,\qquad C_p=\frac52R','2.5*n*8.314*dt','J',{'n':.75,'dt':60},'Nel riscaldamento isobaro il gas aumenta l’energia interna e compie lavoro di espansione. Il calore molare a pressione costante vale cinque mezzi della costante dei gas per il gas monoatomico ideale.')
add(c,'isoterma','Espansioni isoterme reversibili',r'Un gas ideale di $n=@n@\,\mathrm{mol}$ si espande reversibilmente a $T=320\,\mathrm K$ dal volume $V_i=0{,}010\,\mathrm{m^3}$ al volume $V_f=@Vf@\,\mathrm{m^3}$. Calcola il lavoro con $R=8{,}314\,\mathrm{J/(mol\,K)}$.','W',r'W=nRT\ln\frac{V_f}{V_i}','n*8.314*320*log(Vf/.010)','J',{'n':.65,'Vf':.025},'La temperatura resta costante e il gas è ideale, quindi l’energia interna non cambia. Il lavoro reversibile è l’area sotto l’isoterma e contiene il logaritmo naturale del rapporto dei volumi. Il rapporto è maggiore di uno e il lavoro è positivo.','Il calore assorbito ha lo stesso valore del lavoro perché la variazione di energia interna è nulla.')
add(c,'ciclo','Cicli rettangolari nel piano pressione-volume',r'Un gas percorre in senso orario un ciclo rettangolare con pressioni $p_h=@ph@\,\mathrm{Pa}$ e $p_l=1{,}0\cdot10^5\,\mathrm{Pa}$ e volumi $V_l=0{,}002\,\mathrm{m^3}$ e $V_h=@Vh@\,\mathrm{m^3}$. Calcola il lavoro netto.','W',r'W=(p_h-p_l)(V_h-V_l)','(ph-1e5)*(Vh-.002)','J',{'ph':2.6e5,'Vh':.006},'Il lavoro netto è l’area racchiusa dal ciclo. Il percorso orario corrisponde a un’espansione a pressione maggiore della compressione, quindi il lavoro netto è positivo. Le isocore non compiono lavoro di volume.','La variazione di energia interna nel ciclo è zero; il calore netto coincide quindi con il lavoro ottenuto.')

# Secondo principio
c=CH[2][0]
add(c,'rendimento','Rendimenti di macchine termiche',r'Una macchina ciclica assorbe $Q_h=@Qh@\,\mathrm J$ dalla sorgente calda e cede alla fredda $Q_c=@Qc@\,\mathrm J$, entrambi espressi come quantità positive. Calcola il rendimento come numero fra zero e uno.',r'\eta',r'\eta=1-\frac{Q_c}{Q_h}','1-Qc/Qh','',{'Qh':2400,'Qc':1500},'In un ciclo l’energia interna torna al valore iniziale. Il lavoro utile è il calore assorbito meno il modulo di quello ceduto, e il rendimento confronta quel lavoro con il calore assorbito.','Per ottenere la percentuale si moltiplica il risultato per cento.')
add(c,'rendimento','Lavori prodotti dalle macchine',r'Una macchina termica assorbe $Q_h=@Qh@\,\mathrm J$ per ciclo e ha rendimento $\eta=@eta@$. Calcola il lavoro prodotto in un ciclo.','W',r'W=\eta Q_h','eta*Qh','J',{'Qh':1800,'eta':.28},'Il rendimento è il rapporto fra lavoro utile e calore assorbito. Moltiplicandolo per il calore ricevuto si trova il lavoro, che resta inferiore al calore assorbito per i dati assegnati.')
add(c,'rendimento','Calori ceduti dalla macchina',r'Una macchina termica assorbe $Q_h=@Qh@\,\mathrm J$ e produce $W=@W@\,\mathrm J$ per ciclo. Calcola il modulo del calore ceduto alla sorgente fredda.',r'Q_c',r'Q_c=Q_h-W','Qh-W','J',{'Qh':2000,'W':620},'Il fluido ritorna allo stato iniziale in ogni ciclo. Il calore ricevuto si divide quindi fra lavoro e calore ceduto. La quantità ceduta è richiesta come modulo positivo.')
add(c,'carnot','Limiti di Carnot',r'Una macchina opera soltanto fra due sorgenti a $T_h=@Th@\,\mathrm K$ e $T_c=300\,\mathrm K$. Calcola il massimo rendimento possibile come numero fra zero e uno.',r'\eta_C',r'\eta_C=1-\frac{T_c}{T_h}','1-300/Th','',{'Th':650},'Il rendimento massimo fra due sole sorgenti è quello di una macchina reversibile. Le temperature sono assolute e la fredda è minore della calda, quindi il rapporto è inferiore a uno.')
add(c,'frigorifero','Prestazioni dei frigoriferi',r'Un frigorifero sottrae alla sorgente fredda $Q_c=@Qc@\,\mathrm J$ e riceve un lavoro $W=@W@\,\mathrm J$. Calcola il coefficiente di prestazione frigorifero.',r'\mathrm{COP}_f',r'\mathrm{COP}_f=\frac{Q_c}{W}','Qc/W','',{'Qc':720,'W':240},'La prestazione frigorifera confronta l’energia sottratta all’ambiente freddo con il lavoro speso. Può superare uno perché il dispositivo trasferisce energia già presente nella sorgente fredda.','Il calore ceduto all’ambiente caldo è la somma del calore sottratto e del lavoro ricevuto.')
add(c,'entropia','Variazioni di entropia delle sorgenti',r'Una sorgente termica ideale a $T=@T@\,\mathrm K$ cede $Q=@Q@\,\mathrm J$. Calcola la sua variazione di entropia, includendo il segno.',r'\Delta S',r'\Delta S=-\frac QT','-Q/T',r'J/K',{'T':450,'Q':900},'La temperatura della sorgente rimane costante e il calore da essa assorbito è negativo. La sua variazione di entropia è quindi negativa; per il bilancio totale si devono considerare anche i sistemi che ricevono energia.')
add(c,'formule-entropia','Entropie di corpi riscaldati',r'Un corpo con capacità termica costante $C=@C@\,\mathrm{J/K}$ passa da $T_i=300\,\mathrm K$ a $T_f=@Tf@\,\mathrm K$, senza cambiamenti di stato. Calcola la sua variazione di entropia.',r'\Delta S',r'\Delta S=C\ln\frac{T_f}{T_i}','C*log(Tf/300)',r'J/K',{'C':160,'Tf':450},'La temperatura cambia, quindi non si usa un unico rapporto fra calore e temperatura. La formula con il logaritmo deriva dalla somma degli scambi lungo un cammino reversibile fra gli stessi stati. Il risultato è positivo perché il corpo si riscalda.')
add(c,'entropia-totale','Scambi fra due sorgenti',r'Il calore $Q=@Q@\,\mathrm J$ passa da una sorgente a $T_h=@Th@\,\mathrm K$ a una sorgente a $T_c=300\,\mathrm K$. Calcola la variazione totale di entropia delle due sorgenti.',r'\Delta S_{\mathrm{tot}}',r'\Delta S_{\mathrm{tot}}=\frac Q{T_c}-\frac Q{T_h}','Q/300-Q/Th',r'J/K',{'Q':1200,'Th':600},'La sorgente calda perde entropia e quella fredda la acquista. La stessa energia divisa per la temperatura più bassa produce una variazione positiva maggiore in modulo. La somma positiva è coerente con un trasferimento spontaneo irreversibile.')

# Oscillazioni e onde
c=CH[3][0]
add(c,'periodo-frequenza','Frequenze da conteggi di oscillazioni',r'Un oscillatore compie $N=@N@$ oscillazioni complete in $\Delta t=@t@\,\mathrm s$. Calcola la frequenza.','f',r'f=\frac N{\Delta t}','N/t','Hz',{'N':36,'t':12},'La frequenza conta i cicli completi per unità di tempo. Dividendo il numero di oscillazioni per il tempo si ottengono hertz. Il periodo sarebbe il reciproco della frequenza.')
add(c,'massa-molla','Periodi dei sistemi massa-molla',r'Una massa $m=@m@\,\mathrm{kg}$ è collegata a una molla ideale con $k=@k@\,\mathrm{N/m}$ su un piano privo di attrito. Calcola il periodo delle oscillazioni.','T',r'T=2\pi\sqrt{\frac mk}','2*pi*sqrt(m/k)','s',{'m':.45,'k':180},'La forza elastica è proporzionale allo spostamento ed è diretta verso l’equilibrio, quindi il moto è armonico. Il periodo dipende da massa e costante elastica; nell’approssimazione lineare non dipende dall’ampiezza.')
add(c,'moto-armonico','Velocità massime nelle oscillazioni',r'Un oscillatore armonico ha ampiezza $A=@A@\,\mathrm m$ e frequenza $f=@f@\,\mathrm{Hz}$. Calcola il modulo massimo della velocità.',r'v_{\max}',r'v_{\max}=\omega A=2\pi fA','2*pi*f*A','m/s',{'A':.035,'f':2.5},'La velocità massima si raggiunge al passaggio per l’equilibrio. Si trasforma prima la frequenza in pulsazione moltiplicando per due pi greco, poi si moltiplica per l’ampiezza.','Agli estremi dell’oscillazione la velocità è nulla, anche se l’accelerazione ha modulo massimo.')
add(c,'energia-armonica','Energie degli oscillatori elastici',r'Un sistema massa-molla ideale oscilla senza attrito con costante elastica $k=@k@\,\mathrm{N/m}$ e ampiezza $A=@A@\,\mathrm m$. Calcola l’energia meccanica totale.','E',r'E=\frac12kA^2','.5*k*A**2','J',{'k':160,'A':.045},'Agli estremi la velocità è nulla e tutta l’energia meccanica è potenziale elastica. Il valore calcolato resta costante durante il moto senza dissipazione. L’ampiezza compare al quadrato.')
add(c,'pendolo','Periodi dei pendoli semplici',r'Un pendolo semplice di lunghezza $L=@L@\,\mathrm m$ oscilla con piccolo angolo e attriti trascurabili. Usa $g=9{,}81\,\mathrm{m/s^2}$ e calcola il periodo.','T',r'T=2\pi\sqrt{\frac Lg}','2*pi*sqrt(L/9.81)','s',{'L':.80},'Il modello usa massa puntiforme, filo inestensibile e piccole oscillazioni. In queste ipotesi il periodo dipende dalla lunghezza e dall’accelerazione di gravità, mentre la massa non compare.')
add(c,'onda','Lunghezze d’onda dalla velocità',r'Un’onda meccanica si propaga con velocità $u=@u@\,\mathrm{m/s}$ e frequenza $f=@f@\,\mathrm{Hz}$. Calcola la lunghezza d’onda.',r'\lambda',r'u=\lambda f','u/f','m',{'u':24,'f':6},'In un periodo l’onda avanza di una lunghezza d’onda. La relazione fra velocità e frequenza si risolve dividendo la velocità di propagazione per la frequenza. Il risultato è una distanza.')
add(c,'equazione-onda','Velocità delle onde su corde tese',r'Una corda ideale è tesa con forza $F_T=@F@\,\mathrm N$ e ha densità lineare $\mu=@mu@\,\mathrm{kg/m}$. Calcola la velocità delle onde trasversali.','u',r'u=\sqrt{\frac{F_T}{\mu}}','sqrt(F/mu)','m/s',{'F':90,'mu':.012},'La corda è uniforme e si considerano piccole perturbazioni trasversali. Si divide la tensione per la massa per lunghezza e si prende la radice quadrata. La tensione non è una differenza di potenziale elettrico.')
add(c,'onde-stazionarie','Armoniche di corde fissate agli estremi',r'Una corda lunga $L=@L@\,\mathrm m$, fissata ai due estremi, ha velocità d’onda $u=@u@\,\mathrm{m/s}$. Calcola la frequenza della terza armonica.',r'f_3',r'f_n=\frac{nu}{2L}','3*u/(2*L)','Hz',{'L':1.2,'u':120},'Gli estremi sono nodi dello spostamento. Nella terza armonica entrano tre mezze lunghezze d’onda nella corda. Si usa quindi n uguale a tre nella relazione delle frequenze.','La fondamentale vale un terzo del risultato trovato.')
# Suono
c=CH[4][0]
add(c,'suono','Lunghezze d’onda dei suoni',r'Un suono ha frequenza $f=@f@\,\mathrm{Hz}$ in un mezzo dove la velocità vale $u=@u@\,\mathrm{m/s}$. Calcola la lunghezza d’onda.',r'\lambda',r'\lambda=\frac uf','u/f','m',{'f':500,'u':340},'La frequenza indica quante oscillazioni avvengono al secondo, mentre la velocità indica lo spostamento del fronte d’onda in un secondo. Il loro rapporto è la distanza percorsa in un periodo.')
add(c,'eco','Distanze ottenute dall’eco',r'Un impulso sonoro torna alla sorgente dopo una riflessione su una parete con ritardo $\Delta t=@t@\,\mathrm s$. La velocità del suono è $u=340\,\mathrm{m/s}$. Calcola la distanza della parete.','d',r'2d=u\Delta t','340*t/2','m',{'t':.35},'Il tempo misurato comprende andata e ritorno. La distanza complessiva percorsa dall’onda è il doppio della distanza cercata; per questo il prodotto fra velocità e tempo si divide per due.')
add(c,'intensita','Intensità di sorgenti sonore isotrope',r'Una sorgente puntiforme isotropa emette potenza sonora $P=@P@\,\mathrm W$. In campo libero, senza assorbimento né riflessioni, calcola l’intensità a $r=@r@\,\mathrm m$.','I',r'I=\frac P{4\pi r^2}','P/(4*pi*r**2)',r'W/m^2',{'P':.60,'r':3},'La potenza attraversa la superficie della sfera centrata sulla sorgente. L’area cresce con il quadrato del raggio, quindi si divide la potenza per quattro pi greco per il quadrato della distanza.')
add(c,'decibel','Livelli sonori da intensità note',r'In un punto l’intensità sonora è $I=@I@\,\mathrm{W/m^2}$. Con riferimento $I_0=10^{-12}\,\mathrm{W/m^2}$, calcola il livello di intensità sonora.',r'\beta',r'\beta=10\log_{10}\frac I{I_0}','10*log(I/1e-12)/log(10)','dB',{'I':2e-6},'Si forma prima il rapporto senza unità fra intensità e riferimento. Il logaritmo è in base dieci; moltiplicandolo per dieci si ottiene il livello in decibel. Un logaritmo naturale senza conversione darebbe un valore diverso.')
add(c,'battimenti','Frequenze dei battimenti',r'Due suoni puri di ampiezze confrontabili hanno frequenze $f_1=440\,\mathrm{Hz}$ e $f_2=@f2@\,\mathrm{Hz}$. Calcola la frequenza dei battimenti.',r'f_b',r'f_b=|f_2-f_1|','Abs(f2-440)','Hz',{'f2':446},'I battimenti corrispondono alla lenta variazione dell’ampiezza risultante. La loro frequenza è il modulo della differenza delle due frequenze, mentre la frequenza del tono resta vicina alla media.')
add(c,'tubi','Fondamentali dei tubi aperti',r'Un tubo ideale lungo $L=@L@\,\mathrm m$ è aperto a entrambe le estremità. La velocità del suono è $u=340\,\mathrm{m/s}$. Trascurando la correzione degli estremi, calcola la frequenza fondamentale.',r'f_1',r'f_1=\frac u{2L}','340/(2*L)','Hz',{'L':.75},'Le due estremità aperte sono ventri dello spostamento. Nel modo fondamentale fra esse entra mezza lunghezza d’onda, quindi la lunghezza d’onda vale due volte la lunghezza del tubo.')
add(c,'tubi','Fondamentali dei tubi chiusi a un’estremità',r'Un tubo ideale lungo $L=@L@\,\mathrm m$ è chiuso a un’estremità e aperto all’altra. Con $u=340\,\mathrm{m/s}$ e correzione degli estremi trascurabile, calcola la fondamentale.',r'f_1',r'f_1=\frac u{4L}','340/(4*L)','Hz',{'L':.65},'L’estremo chiuso è un nodo dello spostamento e quello aperto un ventre. Nel modo fondamentale la lunghezza contiene un quarto di lunghezza d’onda. La frequenza è quindi la velocità divisa per quattro volte la lunghezza.')
add(c,'doppler','Frequenze ricevute da sorgenti in avvicinamento',r'Una sorgente emette $f=@f@\,\mathrm{Hz}$ e si avvicina a un osservatore fermo nell’aria con velocità $v_s=@vs@\,\mathrm{m/s}$. Il suono si propaga a $u=340\,\mathrm{m/s}$; il moto è lungo la congiungente. Calcola la frequenza ricevuta.',r'f\prime',r'f\prime=f\frac u{u-v_s}','f*340/(340-vs)','Hz',{'f':620,'vs':18},'L’osservatore è fermo rispetto al mezzo e la sorgente è in avvicinamento. I fronti d’onda davanti alla sorgente sono più ravvicinati, quindi si usa il denominatore con la sottrazione. La frequenza ricevuta risulta maggiore di quella emessa.')

# Ottica geometrica
c=CH[5][0]
add(c,'indice','Velocità della luce nei mezzi',r'Un mezzo trasparente ha indice di rifrazione $n=@n@$. Usa $c=3{,}00\cdot10^8\,\mathrm{m/s}$ e calcola la velocità di fase della luce nel mezzo.','u',r'n=\frac cu','3e8/n','m/s',{'n':1.50},'L’indice è il rapporto fra velocità nel vuoto e velocità nel mezzo. Isolando la velocità si divide la costante c per l’indice. Con indice maggiore di uno il risultato è minore di c.')
add(c,'snell','Angoli di rifrazione dall’aria al vetro',r'La luce passa dall’aria, con $n_1=1{,}00$, a un vetro con $n_2=1{,}50$. L’angolo di incidenza rispetto alla normale è $\theta_1=@a@^\circ$. Calcola l’angolo di rifrazione in gradi.',r'\theta_2',r'\theta_2=\arcsin\left(\frac{n_1}{n_2}\sin\theta_1\right)','asin(sin(a*pi/180)/1.5)*180/pi',r'{}^\circ',{'a':35},'La legge di Snell confronta i seni degli angoli misurati dalla normale. Si calcola prima il seno dell’angolo rifratto, poi l’arcoseno. Il mezzo finale ha indice maggiore, quindi l’angolo ottenuto è minore di quello incidente.')
add(c,'angolo-limite','Angoli limite di riflessione totale',r'La luce si propaga da un mezzo di indice $n_1=@n@$ verso l’aria di indice $n_2=1{,}00$. Calcola in gradi l’angolo limite rispetto alla normale.',r'\theta_c',r'\theta_c=\arcsin\frac{n_2}{n_1}','asin(1/n)*180/pi',r'{}^\circ',{'n':1.55},'La riflessione totale può avvenire perché il passaggio è verso un indice minore. Al limite il raggio rifratto sarebbe tangente all’interfaccia, quindi il suo seno vale uno. Si applica l’arcoseno al rapporto fra indice minore e maggiore.')
add(c,'lenti','Immagini reali delle lenti convergenti',r'Una lente sottile convergente ha focale $f=0{,}12\,\mathrm m$. Un oggetto reale si trova a distanza $p=@p@\,\mathrm m$. Nel modello parassiale calcola la distanza immagine con segno, positiva sul lato opposto all’oggetto.','q',r'\frac1f=\frac1p+\frac1q','(.12*p)/(p-.12)','m',{'p':.36},'L’oggetto è oltre la focale, quindi il denominatore nella formula risolta è positivo. La distanza immagine positiva indica un’immagine reale sul lato di uscita della luce.')
add(c,'lenti','Immagini virtuali delle lenti convergenti',r'Una lente sottile convergente ha $f=0{,}20\,\mathrm m$ e un oggetto reale a $p=@p@\,\mathrm m$, dentro la focale. Calcola la distanza immagine con la convenzione $q<0$ per immagini virtuali.','q',r'q=\frac{fp}{p-f}','(.20*p)/(p-.20)','m',{'p':.08},'La distanza dell’oggetto è minore della focale, quindi il denominatore è negativo. Il risultato con segno meno colloca l’immagine sul lato dell’oggetto: si incontrano i prolungamenti dei raggi, non i raggi emergenti.')
add(c,'lenti','Immagini di lenti divergenti',r'Una lente sottile divergente ha focale $f=-0{,}15\,\mathrm m$. L’oggetto reale dista $p=@p@\,\mathrm m$. Calcola la distanza immagine con segno nella convenzione delle lenti.','q',r'q=\frac{fp}{p-f}','(-.15*p)/(p+.15)','m',{'p':.30},'La focale divergente è negativa e va inserita con quel segno. Il denominatore è positivo e il numeratore negativo, quindi l’immagine è virtuale sul lato dell’oggetto. L’ingrandimento meno q diviso p è positivo e minore di uno.')
add(c,'specchi','Immagini di specchi concavi',r'Uno specchio sferico concavo ha focale $f=0{,}18\,\mathrm m$. Un oggetto reale si trova a $p=@p@\,\mathrm m$ davanti allo specchio. In approssimazione parassiale calcola $q$, positiva per immagini reali davanti allo specchio.','q',r'\frac1f=\frac1p+\frac1q','(.18*p)/(p-.18)','m',{'p':.54},'Si usa la focale positiva dello specchio concavo. L’oggetto è oltre il fuoco e la distanza immagine risulta positiva. In questa convenzione l’immagine reale è davanti allo specchio, sul lato della luce riflessa.')
add(c,'diottrie','Poteri diottrici delle lenti',r'Una lente sottile ha distanza focale $f=@f@\,\mathrm m$. Calcola il potere diottrico con segno, in diottrie.','D',r'D=\frac1f','1/f',r'm^{-1}',{'f':.25},'Il potere diottrico è il reciproco della focale espressa in metri. Il segno positivo indica una lente convergente. Usare la focale in centimetri senza conversione produrrebbe un valore cento volte troppo piccolo.')

# Interferenza e diffrazione
c=CH[6][0]
add(c,'luce-onda','Frequenze delle radiazioni luminose',r'Una radiazione nel vuoto ha lunghezza d’onda $\lambda_0=@lam@\,\mathrm m$. Calcola la frequenza usando $c=3{,}00\cdot10^8\,\mathrm{m/s}$.','f',r'f=\frac c{\lambda_0}','3e8/lam','Hz',{'lam':5.5e-7},'La velocità nel vuoto è il prodotto di frequenza e lunghezza d’onda. La lunghezza è già in metri e si isola la frequenza facendo il rapporto. Per lunghezze d’onda maggiori, a velocità fissata, la frequenza diminuisce.')
add(c,'cammino-fase','Sfasamenti prodotti da differenze di cammino',r'Due onde coerenti inizialmente in fase, con $\lambda=600\,\mathrm{nm}$ nello stesso mezzo, arrivano con differenza di cammino $\delta=@delta@\,\mathrm m$. Calcola la differenza di fase in radianti, prima di eventuali riduzioni modulo $2\pi$.',r'\Delta\varphi',r'\Delta\varphi=\frac{2\pi\delta}{\lambda}','2*pi*delta/6e-7','rad',{'delta':4e-7},'Ogni lunghezza d’onda di differenza di cammino corrisponde a due pi greco radianti. Il rapporto fra differenza di cammino e lunghezza d’onda dice quante oscillazioni di fase si accumulano. Il valore richiesto non viene ridotto a un intervallo fondamentale.')
add(c,'young','Interfrange della doppia fenditura',r'Due fenditure sottili distano $d=@d@\,\mathrm m$. La luce ha $\lambda=600\,\mathrm{nm}$ e lo schermo dista $L=2{,}0\,\mathrm m$. Nel campo lontano e per piccoli angoli, calcola la distanza fra massimi adiacenti.',r'\Delta y',r'\Delta y=\frac{\lambda L}{d}','6e-7*2/d','m',{'d':3e-4},'La distanza fra massimi consecutivi si ottiene sottraendo le posizioni di due ordini consecutivi. Nel modello di piccoli angoli resta il prodotto fra lunghezza d’onda e distanza dello schermo diviso la separazione delle fenditure.')
add(c,'young','Posizioni dei massimi di Young',r'In un esperimento di Young $\lambda=550\,\mathrm{nm}$, $L=@L@\,\mathrm m$ e $d=0{,}25\,\mathrm{mm}$. Calcola la distanza dal centro del massimo di ordine positivo $m=2$, usando l’approssimazione dei piccoli angoli.',r'y_2',r'y_m=\frac{m\lambda L}{d}','2*5.5e-7*L/2.5e-4','m',{'L':1.8},'Il massimo centrale ha ordine zero. Il secondo massimo positivo si trova a due interfrange dal centro. La separazione delle fenditure va convertita in metri per mantenere le unità coerenti.')
add(c,'massimo-centrale','Larghezze dei massimi centrali',r'Una fenditura singola larga $a=@a@\,\mathrm m$ è illuminata da luce con $\lambda=600\,\mathrm{nm}$. Lo schermo dista $L=2{,}0\,\mathrm m$. Per piccoli angoli e nel campo lontano, calcola l’intera larghezza fra i primi minimi.',r'w',r'w=\frac{2\lambda L}{a}','2*6e-7*2/a','m',{'a':2e-4},'Il primo minimo laterale dista dal centro lambda per L diviso a. La larghezza comprende il lato positivo e quello negativo, quindi è il doppio di quella distanza. La dimensione a è la larghezza della singola fenditura.')
add(c,'massimo-centrale','Larghezze delle fenditure da figure misurate',r'Una fenditura singola produce su uno schermo a $L=1{,}5\,\mathrm m$ un massimo centrale largo $w=@w@\,\mathrm m$. La luce ha $\lambda=500\,\mathrm{nm}$. Nel modello di piccoli angoli, calcola la larghezza della fenditura.','a',r'a=\frac{2\lambda L}{w}','2*5e-7*1.5/w','m',{'w':.012},'Si risolve la relazione della larghezza centrale rispetto alla dimensione della fenditura. Il fattore due rimane perché la misura assegnata comprende l’intervallo fra i due primi minimi.')
add(c,'reticolo','Angoli dei massimi di un reticolo',r'Un reticolo ha passo $d=2{,}0\cdot10^{-6}\,\mathrm m$ ed è illuminato normalmente da luce di lunghezza d’onda $\lambda=@lam@\,\mathrm m$. Calcola in gradi l’angolo del massimo di primo ordine.',r'\theta_1',r'\theta_1=\arcsin\frac{\lambda}{d}','asin(lam/2e-6)*180/pi',r'{}^\circ',{'lam':5e-7},'Con incidenza normale la differenza di cammino fra righe adiacenti è d per il seno dell’angolo. Per il primo ordine deve essere una lunghezza d’onda. Si ricava l’angolo applicando l’arcoseno al rapporto.')
add(c,'reticolo','Passi dei reticoli',r'Un reticolo contiene $N=@N@$ righe per millimetro. Calcola il passo, cioè la distanza fra righe adiacenti, in metri.','d',r'd=\frac{10^{-3}\,\mathrm m}{N}','1e-3/N','m',{'N':400},'Un millimetro contiene il numero assegnato di intervalli regolari nel modello del reticolo. Si divide quindi un millimetro per il numero di righe, dopo aver espresso il millimetro in metri.')

# Elettrostatica
c=CH[7][0]
add(c,'carica','Cariche dovute a elettroni in eccesso',r'Un corpo ha $N=@N@$ elettroni in eccesso rispetto alla neutralità. Usa $e=1{,}60\cdot10^{-19}\,\mathrm C$ e calcola la carica netta con segno.','q',r'q=-Ne','-N*1.6e-19','C',{'N':4e12},'Ogni elettrone in eccesso aggiunge una carica negativa. Il modulo si ottiene moltiplicando il numero di elettroni per la carica elementare; il segno meno descrive l’eccesso rispetto alla neutralità.')
add(c,'coulomb','Forze fra cariche puntiformi',r'Due cariche puntiformi nel vuoto hanno moduli $|q_1|=@q1@\,\mathrm C$ e $|q_2|=3{,}0\cdot10^{-9}\,\mathrm C$ e distano $r=@r@\,\mathrm m$. Calcola il modulo della forza con $k_e=8{,}99\cdot10^9\,\mathrm{N\,m^2/C^2}$.','F',r'F=k_e\frac{|q_1q_2|}{r^2}','8.99e9*q1*3e-9/r**2','N',{'q1':2e-9,'r':.12},'Il modello puntiforme permette di applicare la legge di Coulomb. Per il modulo si usano i moduli delle cariche e il quadrato della distanza. Il verso richiederebbe anche i segni delle cariche, non necessari per la quantità richiesta.')
add(c,'campo','Campi di cariche puntiformi',r'Una carica puntiforme $Q=@Q@\,\mathrm C$ nel vuoto produce un campo. Calcolane il modulo a distanza $r=0{,}15\,\mathrm m$, con $k_e=8{,}99\cdot10^9\,\mathrm{N\,m^2/C^2}$.','E',r'E=k_e\frac{|Q|}{r^2}','8.99e9*Q/.15**2','N/C',{'Q':4e-9},'Il campo della carica positiva è radiale uscente. Il suo modulo dipende dalla sorgente e dalla distanza, senza introdurre una carica di prova nel risultato.')
add(c,'campo','Forze su cariche in campi uniformi',r'Una particella ha carica $q=-@q@\,\mathrm C$ ed è posta in un campo uniforme di modulo $E=@E@\,\mathrm{N/C}$ diretto verso destra. Calcola il modulo della forza elettrica.','F',r'F=|q|E','q*E','N',{'q':2e-9,'E':450},'La forza è il prodotto fra carica e campo. Il problema chiede il modulo, quindi si usa il valore assoluto della carica. La carica è negativa e la forza è diretta verso sinistra, nel verso opposto al campo.')
add(c,'sovrapposizione','Campi nel punto medio di due cariche positive',r'Due cariche positive $Q_1=@Q1@\,\mathrm C$ a sinistra e $Q_2=1{,}0\cdot10^{-9}\,\mathrm C$ a destra distano $d=0{,}20\,\mathrm m$. Con $k_e=8{,}99\cdot10^9\,\mathrm{N\,m^2/C^2}$, calcola il modulo del campo nel punto medio.','E',r'E=\frac{k_e(Q_1-Q_2)}{(\frac d2)^2}','8.99e9*(Q1-1e-9)/.10**2','N/C',{'Q1':3e-9},'Nel punto medio entrambe le distanze sono metà della separazione. I campi delle due cariche positive hanno versi opposti. La carica sinistra è maggiore, quindi prevale il suo campo verso destra e i moduli si sottraggono.')
add(c,'equilibrio','Punti di annullamento fra cariche uguali in segno',r'Due cariche positive sono $Q$ a sinistra e $4Q$ a destra, a distanza $d=@d@\,\mathrm m$. Calcola la distanza dalla carica $Q$ del punto fra esse dove il campo totale è nullo.','x',r'\frac{Q}{x^2}=\frac{4Q}{(d-x)^2}','d/3','m',{'d':.45},'Fra le sorgenti i campi hanno versi opposti. Uguagliandone i moduli si trova che la distanza dalla carica maggiore deve essere doppia di quella dalla minore. La separazione totale comprende quindi tre parti uguali.')
add(c,'moto-campo','Accelerazioni di elettroni',r'Un elettrone si trova in un campo elettrico uniforme di modulo $E=@E@\,\mathrm{N/C}$. Trascurando altre forze, calcola il modulo dell’accelerazione classica con $e=1{,}60\cdot10^{-19}\,\mathrm C$ e $m_e=9{,}11\cdot10^{-31}\,\mathrm{kg}$.','a',r'a=\frac{eE}{m_e}','1.6e-19*E/9.11e-31',r'm/s^2',{'E':120},'La forza elettrica ha modulo e per E. Il secondo principio della dinamica dà l’accelerazione dividendo la forza per la massa. La direzione è quella del campo ma il verso è opposto, perché l’elettrone ha carica negativa.')
add(c,'linee','Momenti torcenti sui dipoli',r'Un dipolo ha cariche di modulo $q=@q@\,\mathrm C$ separate da $d=0{,}020\,\mathrm m$. È perpendicolare a un campo uniforme $E=800\,\mathrm{N/C}$. Calcola il modulo del momento torcente.','M',r'M=pE\sin\theta=qdE','q*.020*800','N m',{'q':1.5e-9},'Il momento di dipolo ha modulo q per la separazione. L’angolo è retto e il suo seno vale uno, quindi il momento torcente ha valore massimo. Le forze sulle cariche si compensano come risultante ma formano una coppia.')
# Flusso e Gauss
c=CH[8][0]
add(c,'flusso','Flussi attraverso superfici piane',r'Un campo elettrico uniforme ha modulo $E=@E@\,\mathrm{N/C}$. Attraversa una superficie piana di area $A=0{,}040\,\mathrm{m^2}$ formando $60^\circ$ con la normale scelta. Calcola il flusso con segno.',r'\Phi_E',r'\Phi_E=EA\cos\theta','E*.040*cos(pi/3)',r'N m^2/C',{'E':250},'La formula usa l’angolo con la normale. Il coseno di sessanta gradi vale un mezzo ed è positivo, quindi il flusso è metà del prodotto fra campo e area. Invertire la normale cambierebbe il segno.')
add(c,'gauss','Cariche ricavate dal flusso chiuso',r'Il flusso totale uscente da una superficie chiusa nel vuoto vale $\Phi_E=@phi@\,\mathrm{N\,m^2/C}$. Calcola la carica netta interna con $\varepsilon_0=8{,}85\cdot10^{-12}\,\mathrm{C^2/(N\,m^2)}$.',r'Q_{\mathrm{int}}',r'Q_{\mathrm{int}}=\varepsilon_0\Phi_E','8.85e-12*phi','C',{'phi':240},'La superficie è chiusa, quindi si applica il teorema di Gauss. Il flusso è positivo e indica carica netta interna positiva. Il teorema dà la somma algebrica, senza distinguere le singole cariche presenti.')
add(c,'gauss','Flussi con cariche interne ed esterne',r'Una superficie chiusa racchiude le cariche $q_1=@q1@\,\mathrm C$ e $q_2=-1{,}0\cdot10^{-9}\,\mathrm C$. All’esterno c’è $q_3=5{,}0\cdot10^{-9}\,\mathrm C$. Calcola il flusso totale con $\varepsilon_0=8{,}85\cdot10^{-12}\,\mathrm{C^2/(N\,m^2)}$.',r'\Phi_E',r'\Phi_E=\frac{q_1+q_2}{\varepsilon_0}','(q1-1e-9)/8.85e-12',r'N m^2/C',{'q1':3e-9},'Nel teorema compare solo la carica racchiusa, con la somma dei segni. La carica esterna modifica il campo sulla superficie ma contribuisce flusso netto nullo attraverso la superficie chiusa.')
add(c,'sfera','Campi esterni di sfere cariche',r'Una distribuzione sfericamente simmetrica ha carica totale $Q=@Q@\,\mathrm C$ e raggio $R=0{,}050\,\mathrm m$. Calcola il modulo del campo a $r=0{,}20\,\mathrm m$ con $\varepsilon_0=8{,}85\cdot10^{-12}\,\mathrm{C^2/(N\,m^2)}$.','E',r'E=\frac{Q}{4\pi\varepsilon_0r^2}','Q/(4*pi*8.85e-12*.20**2)','N/C',{'Q':2e-9},'Il punto è esterno e la distribuzione è sfericamente simmetrica. Su una sfera gaussiana il campo è radiale e uniforme in modulo; il flusso è quindi il campo per l’area della sfera. La carica racchiusa è quella totale.')
add(c,'sfera-uniforme','Campi interni di sfere isolanti uniformi',r'Una sfera isolante di raggio $R=0{,}10\,\mathrm m$ contiene carica uniforme totale $Q=@Q@\,\mathrm C$. Calcola il campo in modulo a $r=0{,}040\,\mathrm m$ con $\varepsilon_0=8{,}85\cdot10^{-12}\,\mathrm{C^2/(N\,m^2)}$.','E',r'E=\frac{Qr}{4\pi\varepsilon_0R^3}','Q*.040/(4*pi*8.85e-12*.10**3)','N/C',{'Q':1e-9},'La sfera gaussiana interna racchiude una frazione della carica proporzionale al cubo del proprio raggio. Dopo aver diviso per l’area della superficie gaussiana resta un campo proporzionale alla distanza dal centro.')
add(c,'filo','Campi di fili uniformemente carichi',r'Un filo rettilineo idealmente indefinito ha densità lineare $\lambda_q=@lq@\,\mathrm{C/m}$. Calcola il modulo del campo a distanza $r=0{,}080\,\mathrm m$ con $\varepsilon_0=8{,}85\cdot10^{-12}\,\mathrm{C^2/(N\,m^2)}$.','E',r'E=\frac{|\lambda_q|}{2\pi\varepsilon_0r}','lq/(2*pi*8.85e-12*.080)','N/C',{'lq':1.2e-9},'La simmetria cilindrica permette una superficie gaussiana coassiale al filo. Solo la superficie laterale contribuisce al flusso. Il campo dipende dall’inverso della distanza, diverso dalla dipendenza quadratica della carica puntiforme.')
add(c,'piano','Campi di piani uniformemente carichi',r'Un piano isolante idealmente indefinito ha densità superficiale uniforme $\sigma_q=@sig@\,\mathrm{C/m^2}$. Calcola il campo in modulo su uno dei due lati, con $\varepsilon_0=8{,}85\cdot10^{-12}\,\mathrm{C^2/(N\,m^2)}$.','E',r'E=\frac{|\sigma_q|}{2\varepsilon_0}','sig/(2*8.85e-12)','N/C',{'sig':1.5e-8},'Il piano produce flusso attraverso le due basi di un cilindro gaussiano simmetrico. Le due superfici contribuiscono ugualmente, quindi il denominatore contiene il fattore due. Nel modello infinito il modulo non dipende dalla distanza.')
add(c,'due-piani','Campi fra armature piane opposte',r'Due armature piane parallele hanno densità superficiali $+\sigma_q$ e $-\sigma_q$, con $\sigma_q=@sig@\,\mathrm{C/m^2}$. Trascurando i bordi, calcola il modulo del campo fra esse con $\varepsilon_0=8{,}85\cdot10^{-12}\,\mathrm{C^2/(N\,m^2)}$.','E',r'E=\frac{\sigma_q}{\varepsilon_0}','sig/8.85e-12','N/C',{'sig':8e-9},'Fra le armature i due campi hanno lo stesso verso e si sommano. Ciascun piano dà metà del risultato totale; il campo finale va dall’armatura positiva a quella negativa.')

# Potenziale e condensatori
c=CH[9][0]
add(c,'potenziale','Potenziali di cariche puntiformi',r'Una carica puntiforme positiva $Q=@Q@\,\mathrm C$ si trova nel vuoto. Calcola il potenziale a $r=0{,}20\,\mathrm m$, ponendo zero all’infinito e usando $k_e=8{,}99\cdot10^9\,\mathrm{N\,m^2/C^2}$.','V',r'V=k_e\frac Qr','8.99e9*Q/.20','V',{'Q':3e-9},'Il potenziale è una grandezza scalare. Per una sorgente positiva e riferimento all’infinito il valore è positivo e diminuisce con la distanza. La distanza compare alla prima potenza, a differenza del campo.')
