SYMBOL_NAMES={'dt':r'\Delta T','mh':'m_h','mc':'m_c','tf':'t_f','p1':'p_1','T2':'T_2','Vf':'V_f','du':r'\Delta U','ph':'p_h','Vh':'V_h','Qh':'Q_h','Qc':'Q_c','eta':r'\eta','Th':'T_h','Tf':'T_f','mu':r'\mu','f2':'f_2','vs':'v_s','lam':r'\lambda','delta':r'\delta','q1':'q_1','Q1':'Q_1','phi':r'\Phi_E','lq':r'\lambda_q','sig':r'\sigma_q','C1':'C_1','R0':'R_0','R1':'R_1','Rs':'R_s','I1':'I_1','emf':r'\mathcal E','V0':'V_0'}
FACTORS=[.8,1.0,1.2,1.4,1.6,1.8,.9,1.1,1.3]

def instance(t,idx):
    vals=dict(t['values']); variable=next(iter(vals)); base=vals[variable]
    vals[variable]=440+(base-440)*FACTORS[idx] if variable=='f2' else base*FACTORS[idx]
    if variable=='N': vals[variable]=round(vals[variable])
    # Tutti i dati visibili sono arrotondati a tre cifre, quindi i conti usano proprio quei dati.
    vals={k:float(f'{v:.3g}') for k,v in vals.items()}
    loc={k:sp.Symbol(k,real=True) for k in vals}
    loc.update(pi=sp.pi,log=sp.log,sqrt=sp.sqrt,exp=sp.exp,Abs=sp.Abs)
    expr=sp.sympify(t['expr'],locals=loc,evaluate=False)
    result=float(expr.subs({loc[k]:v for k,v in vals.items()}))
    assert math.isfinite(result)
    stem=t['prompt']
    for k,v in vals.items(): stem=stem.replace('@'+k+'@',num(v))
    symbolic=sp.latex(expr,mul_symbol='dot',symbol_names={loc[k]:SYMBOL_NAMES.get(k,k) for k in vals})
    numeric=sp.latex(expr,mul_symbol='dot',symbol_names={loc[k]:num(v) for k,v in vals.items()})
    symbolic=re.sub(r'(?<=\d)\.(?=\d)','{,}',symbolic)
    numeric=re.sub(r'(?<=\d)\.(?=\d)','{,}',numeric)
    unit=(r'\,\mathrm{'+t['unit']+'}') if t['unit'] else ''
    answer=t['target']+'='+num(result)+unit
    calculation=r'\begin{aligned}'+ '\n' +t['target']+' &= '+symbolic+r' \\[6pt]'+'\n&= '+numeric+unit+r' \\[6pt]'+'\n&\\simeq '+num(result)+unit+'\n'+r'\end{aligned}'
    return dict(vals=vals,result=result,stem=stem,symbolic=symbolic,numeric=numeric,unit=unit,answer=answer,calculation=calculation,expr=expr,loc=loc)

def front(title,anchor,gratis=None):
    s='---\ntitolo: '+json.dumps(title,ensure_ascii=False)+'\n'
    if gratis is not None: s+='gratis: '+str(gratis).lower()+'\n'
    return s+'teoria: ['+anchor+']\nparole: '+json.dumps([title],ensure_ascii=False)+'\n---\n\n'

def save(coll,ch,n,text):
    p=OUT/coll/M/ch/(str(n)+'.md');p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text+'\n')

def graph(t,a):
    var=next(iter(a['vals'])); x=sp.Symbol('x')
    repl={a['loc'][k]:(a['vals'][k]*x if k==var else a['vals'][k]) for k in a['vals']}
    if var=='f2': repl[a['loc'][var]]=440+(a['vals'][var]-440)*x
    f=sp.simplify(a['expr'].subs(repl)/a['result'])
    if f.has(sp.Abs): f=f.replace(sp.Abs,lambda y: y) # solo intervallo positivo dei problemi generati
    js=sp.jscode(f).replace('Math.','')
    if 'pow(' in js: # jscode produce pow; il motore delle figure accetta potenze JavaScript
        js=js.replace('pow(', 'Math.pow(')
    lo=.9; hi=1.8
    ys=[float(f.subs(x,v)) for v in [lo,1,hi]]
    ymin=0 if min(ys)>=0 else math.floor(min(ys))
    ymax=max(2,math.ceil(max(ys)+.2))
    input_tex=r'(f_2-440\,\mathrm{Hz})' if var=='f2' else SYMBOL_NAMES.get(var,var)
    return f'::grafico{{f="{js}" punti="1,1,pieno" xmin={lo} xmax={hi} ymin={ymin} ymax={ymax} nomi="x/x₀,y/y₀" titolo="Variazione di ${t['target']}$ al variare di ${input_tex}$, entrambe divise per il rispettivo valore calcolato; gli altri dati restano fissi e il punto $(1,1)$ rappresenta il caso dell’esercizio"}}'

def extra_exercise(t,a,ci,j):
    question,steps,why=EXTRA[ci][j]
    calculations=[]
    for target,formula,expression,unitname in steps:
        vals=dict(a['vals'],z=a['result'])
        loc={k:sp.Symbol(k,real=True) for k in vals}
        loc.update(pi=sp.pi,log=sp.log,sqrt=sp.sqrt,exp=sp.exp,Abs=sp.Abs,asin=sp.asin,sin=sp.sin,cos=sp.cos)
        expr=sp.sympify(expression,locals=loc,evaluate=False)
        result=float(expr.subs({loc[k]:v for k,v in vals.items()}))
        assert math.isfinite(result)
        symbolic=sp.latex(expr,mul_symbol='dot',symbol_names={loc[k]:(t['target'] if k=='z' else SYMBOL_NAMES.get(k,k)) for k in vals})
        numeric=sp.latex(expr,mul_symbol='dot',symbol_names={loc[k]:num(v) for k,v in vals.items()})
        symbolic=re.sub(r'(?<=\d)\.(?=\d)','{,}',symbolic)
        numeric=re.sub(r'(?<=\d)\.(?=\d)','{,}',numeric)
        unit=(r'\,\mathrm{'+unitname+'}') if unitname else ''
        calc=r'\begin{aligned}'+'\n'+target+' &= '+symbolic+r' \\[6pt]'+'\n'+r'&\simeq '+numeric+unit+r' \\[6pt]'+'\n'+r'&\simeq '+num(result)+unit+'\n'+r'\end{aligned}'
        calculations.append('$$\n'+formula+'\n$$\n\n$$\n'+calc+'\n$$\n\n')
        AUDIT.append(dict(kind='svolti-collegati',chapter=CH[ci][0],file=j+1,expression=expression,parameters=vals,result=result,answer=target+'='+num(result)+unit))
    return question,''.join(calculations),why

practice_titles=json.loads((Path(__file__).parent/'titoli_tracce.json').read_text())
concepts=json.loads((Path(__file__).parent/'concetti.json').read_text())
for ci,(ch,title,brief) in enumerate(CH):
    ts=BANK[ch];assert len(ts)==8
    for j,t in enumerate(ts):
        text=front(t['title'],t['anchor'],j<3)
        for ex,idx in enumerate([0,1],1):
            a=instance(t,idx)
            extraq,extracalc,extrawhy=extra_exercise(t,a,ci,j) if ex==2 else ('','','')
            if extraq: a['stem']+=' '+extraq
            text+=f"## Esercizio {ex}\n\n{a['stem']}\n\n$$\n{t['formula']}\n$$\n\n"
            text+='$$\n'+a['calculation']+'\n$$\n\n'
            if ex==1 and j in [0,2,4,6]: text+=graph(t,a)+'\n\n'
            text+=extracalc
            text+='<div class="spiegazione">\n\n'+t['why']+'\n\n'
            if extrawhy: text+=extrawhy+'\n\n'
            if t['scale']: text+=t['scale']+'\n\n'
            text+='</div>\n\n'
            AUDIT.append(dict(kind='svolti',chapter=ch,file=j+1,exercise=ex,expression=t['expr'],parameters=a['vals'],result=a['result'],answer=a['answer']))
        save('svolti',ch,j+1,text)
    for j in range(14):
        t=ts[j%8];a=instance(t,2+j//8)
        ptitle=practice_titles[ci][j%8]
        for key,value in a['vals'].items():
            plain=f'{value:.3g}'
            if 'e' in plain:
                mantissa,exponent=plain.split('e')
                plain=mantissa+' × 10'+str(int(exponent)).translate(str.maketrans('0123456789-','⁰¹²³⁴⁵⁶⁷⁸⁹⁻'))
            ptitle=ptitle.replace('@'+key+'@',plain.replace('.',','))
        save('dafare',ch,j+1,front(ptitle,t['anchor'])+a['stem']+'\n\n:::soluzione\n$'+a['answer']+'$.\n:::')
        AUDIT.append(dict(kind='dafare',chapter=ch,file=j+1,expression=t['expr'],parameters=a['vals'],result=a['result'],answer=a['answer']))
    qn=0
    for j,t in enumerate(ts):
        for idx in range(4,9 if j<6 else 8):
            qn+=1;a=instance(t,idx);v=a['result']
            factors=[.5,2,4,.25,10,-1]
            choices=[a['answer']];seen={num(v)}
            for factor in factors:
                display=num(v*factor)
                if display not in seen:
                    choices.append(t['target']+'='+display+a['unit']);seen.add(display)
                if len(choices)==4: break
            assert len(choices)==4
            correct=(qn+ci)%4
            choices.insert(correct,choices.pop(0))
            text='---\ncorretta: '+str(correct+1)+'\n---\n\n'+a['stem']+'\n\n'+'\n'.join('- $'+s+'$.' for s in choices)
            text+='\n\n## Spiegazione\n\n'+t['why']+'\n\n$$\n'+a['calculation']+'\n$$\n\n[Teoria](/'+M+'/'+ch+'/teoria#'+t['anchor']+').'
            save('domande',ch,qn,text)
            AUDIT.append(dict(kind='domande',chapter=ch,file=qn,expression=t['expr'],parameters=a['vals'],result=v,correct=correct+1,choices=choices,answer=a['answer']))
    assert qn==38
    for item in concepts[ci]:
        qn+=1;stem,correctans,*rest=item;wrong=rest[:3];why=rest[3]
        choices=[correctans]+wrong;correct=(qn+ci)%4;choices.insert(correct,choices.pop(0))
        text='---\ncorretta: '+str(correct+1)+'\n---\n\n'+stem+'\n\n'+'\n'.join('- '+s+'.' for s in choices)
        text+='\n\n## Spiegazione\n\n'+why+'\n\n[Teoria](/'+M+'/'+ch+'/teoria).'
        save('domande',ch,qn,text)
    assert qn==45
(Path(__file__).parent/'risultati-numerici.json').write_text(json.dumps(AUDIT,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'capitoli':len(CH),'schede_svolte':96,'esercizi_svolti':192,'esercizi_da_fare':168,'quiz':540,'risultati_calcolati':len(AUDIT)},ensure_ascii=False))
